// 更新分享彈窗內的喜歡清單預覽
function updateSharePreviewList() {
  const previewBox = document.getElementById('shareSelectedPreview');
  const countBadge = document.getElementById('shareSelectedCount');
  if (countBadge) countBadge.textContent = favoriteIds.size;

  if (!previewBox) return;

  if (favoriteIds.size === 0) {
    previewBox.innerHTML = `<span style="color: #94a3b8;">⚠️ 您目前尚未標記任何喜歡的活動，請回到清單點擊卡片右上角標記喜歡！❤️</span>`;
    return;
  }

  const list = activitiesData.filter(a => favoriteIds.has(a.id));
  previewBox.innerHTML = `
    <div style="display: flex; flex-direction: column; gap: 4px;">
      ${list.map((act, i) => `
        <div style="display: flex; justify-content: space-between; align-items: center; border-bottom: 1px dashed rgba(255,255,255,0.06); padding: 3px 0;">
          <span>${i + 1}. <strong>${act.title}</strong></span>
          <span style="color: #a5b4fc; font-size: 0.75rem;">${act.category}</span>
        </div>
      `).join('')}
    </div>
  `;
}

// 產生並複製分享碼 (健全的 UTF-8 Base64 編碼，依據個人喜歡 favoriteIds)
function generateAndCopyShareCode() {
  const nameInput = document.getElementById('shareUserNickname');
  let nickname = nameInput ? nameInput.value.trim() : '';

  if (!nickname) {
    nickname = prompt('請輸入您的社員暱稱（例如：阿鐵、悠悠、奇奇）：');
    if (!nickname) nickname = '熱心社員';
    if (nameInput) nameInput.value = nickname;
  }
  localStorage.setItem(STORAGE_KEYS.USER_NICKNAME, nickname);

  if (favoriteIds.size === 0) {
    alert('您尚未標記任何喜歡的活動！請先在卡片上標記想參加的活動企劃後再匯出。');
    return;
  }

  const votePayload = {
    v: 1,
    name: nickname,
    time: new Date().toLocaleString([], { month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' }),
    selectedIds: Array.from(favoriteIds)
  };

  try {
    const jsonStr = JSON.stringify(votePayload);
    // 安全的 UTF-8 編碼至 Base64
    const base64Code = btoa(encodeURIComponent(jsonStr).replace(/%([0-9A-F]{2})/g, (match, p1) => {
      return String.fromCharCode('0x' + p1);
    }));
    const finalCode = `MYVOTE:${base64Code}`;

    navigator.clipboard.writeText(finalCode).then(() => {
      showToast(`✅ 分享碼已複製！快發送給幹部或社團群組吧！`);
    }).catch(() => {
      prompt('請複製以下分享代碼：', finalCode);
    });
  } catch (err) {
    console.error('Base64 encode error:', err);
    alert('生成分享碼時發生錯誤，請重試。');
  }
}

// 匯入社員分享碼 (支援模糊擷取與容錯)
function importMemberShareCode() {
  const input = document.getElementById('importShareCodeInput');
  if (!input) return;
  const rawCode = input.value.trim();

  if (!rawCode) {
    alert('請貼上社員的分享碼！');
    return;
  }

  try {
    let payload = null;

    // 1. 嘗試由 MYVOTE: 前綴提取
    const match = rawCode.match(/(?:MYVOTE:)?([A-Za-z0-9+/=]{12,})/);
    if (match && match[1]) {
      try {
        const b64 = match[1];
        const decodedUri = decodeURIComponent(atob(b64).split('').map(c => {
          return '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2);
        }).join(''));
        payload = JSON.parse(decodedUri);
      } catch (e1) {
        // 回退嘗試直接 JSON parse
        payload = JSON.parse(rawCode);
      }
    } else {
      payload = JSON.parse(rawCode);
    }

    if (!payload || !payload.name || !Array.isArray(payload.selectedIds)) {
      throw new Error('格式不符合投票結構');
    }

    const existingIndex = memberVotes.findIndex(v => v.name === payload.name);
    const newRecord = {
      id: `vote-${Date.now()}`,
      name: payload.name,
      time: payload.time || new Date().toLocaleString(),
      selectedIds: payload.selectedIds
    };

    if (existingIndex >= 0) {
      memberVotes[existingIndex] = newRecord;
      showToast(`已更新社員「${payload.name}」的活動投票（共 ${payload.selectedIds.length} 項）！`);
    } else {
      memberVotes.unshift(newRecord);
      showToast(`已成功匯入社員「${payload.name}」的活動投票（共 ${payload.selectedIds.length} 項）！`);
    }

    saveMemberVotes();
    updateVoteBadges();
    renderModalMemberVotesList();
    input.value = '';
    closeShareModal();

    // 關鍵修復：匯入社員後，立即刷新並切換至統計視圖，確保統計圖表與社員標籤第一時間渲染！
    handleCategoryTabSwitch('stats');
  } catch (e) {
    alert('分享碼解析失敗，請確認代碼是否完整複製（可包含 MYVOTE:）！');
    console.error('Import error:', e);
  }
}

// 載入示範投票
function loadDemoVotesAction() {
  memberVotes = JSON.parse(JSON.stringify(DEMO_VOTES));
  saveMemberVotes();
  updateVoteBadges();
  renderModalMemberVotesList();
  closeShareModal();
  showToast('已載入三位社員（阿鐵、悠悠、奇奇）示範投票！');
  
  // 關鍵修復：載入示範投票後立即刷新統計視圖
  handleCategoryTabSwitch('stats');
}

// 渲染彈窗內「已匯入社員紀錄管理」清單
function renderModalMemberVotesList() {
  const container = document.getElementById('modalMemberVotesList');
  const countSpan = document.getElementById('modalMemberVotesCount');
  if (countSpan) countSpan.textContent = memberVotes.length;
  if (!container) return;

  if (memberVotes.length === 0) {
    container.innerHTML = `
      <div style="text-align: center; color: #64748b; font-size: 0.82rem; padding: 12px 0;">
        目前尚無任何已匯入社員紀錄
      </div>
    `;
    return;
  }

  container.innerHTML = memberVotes.map(vote => {
    const actCount = (vote.selectedIds || []).length;
    return `
      <div class="modal-member-item">
        <div class="modal-member-info">
          <span class="modal-member-name">👤 ${vote.name}</span>
          <span class="modal-member-count">投了 ${actCount} 項</span>
          <span style="font-size: 0.72rem; color: #64748b;">${vote.time || ''}</span>
        </div>
        <button class="btn-delete-member-sm" onclick="deleteMemberVote('${vote.id}')" type="button" title="刪除此社員紀錄，其所投選票與統計計數將立即扣除">
          🗑️ 刪除
        </button>
      </div>
    `;
  }).join('');
}

// 刪除個別社員投票紀錄 (單人刪除，連帶統計票數、圖表與頂部計數即時扣除)
function deleteMemberVote(voteId) {
  const target = memberVotes.find(v => v.id === voteId);
  const name = target ? target.name : '此社員';
  if (!confirm(`確定要刪除社員「${name}」的投票紀錄嗎？\n刪除後該社員投下的所有票數與各項計數將會同步扣除。`)) return;

  memberVotes = memberVotes.filter(v => v.id !== voteId);
  if (activeMemberFilter === voteId) {
    activeMemberFilter = null;
    renderActiveMemberBanner();
  }
  saveMemberVotes();
  updateVoteBadges();           // 即時扣除頂部/分頁標籤「📊 社員投票統計 (N人)」！
  renderModalMemberVotesList(); // 即時更新彈窗內已匯入清單
  renderMemberQuickFilterChips();
  renderStatsView();            // 即時重算長條圖、圓餅圖、排行榜票數與方框清單
  updateSubTypeBadges();
  renderCards();
  showToast(`已成功移除社員「${name}」的紀錄，其餘計數已同步扣除！`);
}

// 一鍵清空所有社員投票紀錄
function clearAllMemberVotes() {
  if (memberVotes.length === 0) {
    alert('目前尚無任何已匯入紀錄。');
    return;
  }
  if (!confirm(`確定要清空全部共 ${memberVotes.length} 位社員的投票紀錄嗎？\n此動作將歸零所有統計排行榜與圖表數據。`)) return;

  memberVotes = [];
  activeMemberFilter = null;
  renderActiveMemberBanner();
  saveMemberVotes();
  updateVoteBadges();           // 即時更新頂部/分頁標籤歸零
  renderModalMemberVotesList(); // 即時更新彈窗清空
  renderMemberQuickFilterChips();
  renderStatsView();            // 統計頁顯示無紀錄空狀態
  updateSubTypeBadges();
  renderCards();
  showToast('已清空全部社員投票紀錄，統計數據已歸零。');
}

// ==========================================================================
// 2. 社員投票統計專區 (Stats & Charts Rendering)
// ==========================================================================
function renderStatsView() {
  const container = document.getElementById('statsContainer');
  if (!container) return;

  if (memberVotes.length === 0) {
    container.innerHTML = `
      <div class="empty-state" style="padding: 80px 20px;">
        <div class="empty-state-icon">📊</div>
        <h3>目前尚無任何社員投票紀錄</h3>
        <p>邀請社員勾選心儀活動並匯出分享碼，在此匯入後即可生成熱門排行與圓餅統計！</p>
        <button class="btn-action" onclick="loadDemoVotesAction()" style="margin-top: 16px; background: linear-gradient(135deg, #6366f1, #a855f7); color: #fff;">
          👥 一鍵載入三位社員示範投票
        </button>
      </div>
    `;
    return;
  }

  // 1. 全社總得票統計（做為全社比較基準）
  const allVoteCounts = {};
  const allGameCounts = { 'hsr': 0, 'genshin': 0, 'zzz': 0, 'other': 0 };
  const allTypeCounts = { 'casual': 0, 'score': 0, 'craft': 0 };

  memberVotes.forEach(vote => {
    (vote.selectedIds || []).forEach(id => {
      allVoteCounts[id] = (allVoteCounts[id] || 0) + 1;
      const act = activitiesData.find(a => a.id === id);
      if (act) {
        if (allGameCounts[act.categoryKey] !== undefined) {
          allGameCounts[act.categoryKey]++;
        } else {
          allGameCounts['other']++;
        }
        if (allTypeCounts[act.subTypeKey] !== undefined) {
          allTypeCounts[act.subTypeKey]++;
        }
      }
    });
  });

  const totalVotesCast = Object.values(allVoteCounts).reduce((a, b) => a + b, 0);

  // 判斷是否處於單一社員篩選模式
  const targetMember = activeMemberFilter ? memberVotes.find(v => v.id === activeMemberFilter) : null;
  const isMemberMode = Boolean(targetMember);

  // 根據是否篩選社員，計算要在圖表與排行榜中展示的數據
  let displayTypeCounts = { 'casual': 0, 'score': 0, 'craft': 0 };
  let rankedActivities = [];

  if (isMemberMode) {
    // 該社員所選的心願活動，依全社得票由高到低排序
    const memberActIds = targetMember.selectedIds || [];
    rankedActivities = memberActIds.map(id => {
      const act = activitiesData.find(a => a.id === id);
      if (act && displayTypeCounts[act.subTypeKey] !== undefined) {
        displayTypeCounts[act.subTypeKey]++;
      }
      return {
        id: id,
        count: allVoteCounts[id] || 1, // 顯示該活動在全社累積的總票數
        act: act
      };
    }).filter(item => item.act).sort((a, b) => b.count - a.count);
  } else {
    // 全體綜合排行
    displayTypeCounts = allTypeCounts;
    rankedActivities = Object.keys(allVoteCounts).map(id => {
      return {
        id: id,
        count: allVoteCounts[id],
        act: activitiesData.find(a => a.id === id)
      };
    }).filter(item => item.act).sort((a, b) => b.count - a.count);
  }

  // 儲存排行榜作為統計頁彈窗的切換上下文池
  currentModalContextPool = rankedActivities.map(r => r.act);

  // 繪製圓餅圖 (SVG Donut Chart)
  const pieSVG = createDonutChartSVG(displayTypeCounts);

  // 3. 預先產生社員快速篩選標籤按鈕 HTML (確保一體化渲染時 100% 立即呈現按鈕)
  const allChipHTML = `
    <button class="btn-member-filter-chip ${!isMemberMode ? 'active' : ''}" 
            onclick="clearMemberFilter()" type="button" title="檢視全社綜合統計圖表 (無社員篩選)">
      <svg class="mono-icon" viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
        <path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"></path>
        <circle cx="9" cy="7" r="4"></circle>
        <path d="M23 21v-2a4 4 0 0 0-3-3.87"></path>
        <path d="M16 3.13a4 4 0 0 1 0 7.75"></path>
      </svg>
      <span>全部</span>
    </button>
  `;
  const memberChipsHTML = memberVotes.map(vote => {
    const isActive = activeMemberFilter === vote.id;
    const count = (vote.selectedIds || []).length;
    return `
      <button class="btn-member-filter-chip ${isActive ? 'active' : ''}" 
              onclick="filterByMember('${vote.id}')" type="button" title="在圖表中顯示社員「${vote.name}」所選的心願活動">
        <svg class="mono-icon" viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
          <path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"></path>
          <circle cx="12" cy="7" r="4"></circle>
        </svg>
        <span>${vote.name}</span>
        <span class="chip-badge">${count}</span>
      </button>
    `;
  }).join('');

  // 4. 定義各視圖文案與卡片指標
  const headerBadgeText = isMemberMode 
    ? `👤 社員專屬分析 · ${targetMember.name}` 
    : `👥 社員投票分析`;
  const headerSubtitleText = isMemberMode
    ? `目前正在圖表中檢視社員「${targetMember.name}」所勾選之 ${rankedActivities.length} 項心願活動與性質偏好（點擊「全部」可返回全社總覽）`
    : `已自動彙整所有社員匯入之心願活動代碼，即時統計得票榜單、性質圓餅比例與個別社員選項方框`;

  const statCard1 = isMemberMode
    ? `
      <div class="stat-metric-card is-member-highlight">
        <span class="stat-label">👤 當前社員</span>
        <div class="stat-val stat-val-sky" style="font-size: 1.25rem;">${targetMember.name}</div>
      </div>
    `
    : `
      <div class="stat-metric-card">
        <span class="stat-label">👥 已參社員</span>
        <div class="stat-val stat-val-sky">${memberVotes.length} 位</div>
      </div>
    `;

  const statCard2 = isMemberMode
    ? `
      <div class="stat-metric-card is-member-highlight">
        <span class="stat-label">🎟️ 心願項目</span>
        <div class="stat-val stat-val-emerald">${rankedActivities.length} 項</div>
      </div>
    `
    : `
      <div class="stat-metric-card">
        <span class="stat-label">🎟️ 累積票數</span>
        <div class="stat-val stat-val-emerald">${totalVotesCast} 票</div>
      </div>
    `;

  const statCard3 = isMemberMode
    ? `
      <div class="stat-metric-card is-member-highlight">
        <span class="stat-label">🔥 熱門活動</span>
        <div class="stat-val stat-val-amber">${rankedActivities[0] ? rankedActivities[0].count + ' 票' : '0 票'}</div>
      </div>
    `
    : `
      <div class="stat-metric-card">
        <span class="stat-label">🔥 熱門活動</span>
        <div class="stat-val stat-val-amber">${rankedActivities[0] ? rankedActivities[0].count + ' 票' : '0 票'}</div>
      </div>
    `;

  const statCard4 = `
    <div class="stat-metric-card stat-card-wide">
      <span class="stat-label">${isMemberMode ? '🏆 該社員首選人氣企劃' : '🏆 最高人氣企劃'}</span>
      <div class="stat-val-highlight" title="${rankedActivities[0] ? rankedActivities[0].act.title : '暫無'}">
        ${rankedActivities[0] ? rankedActivities[0].act.title : '暫無'}
      </div>
    </div>
  `;

  // 長條圖資料渲染 (若為社員專屬則顯示其所選活動，最多 10 項；全社模式則 Top 6)
  const barChartDisplayItems = isMemberMode ? rankedActivities.slice(0, 10) : rankedActivities.slice(0, 6);
  const barChartTitle = isMemberMode
    ? `📊 社員「${targetMember.name}」所選活動得票圖 (共 ${rankedActivities.length} 項)`
    : `📊 活動熱門得票長條圖 (Top 6)`;

  const pieChartTitle = isMemberMode
    ? `🥧 社員「${targetMember.name}」活動性質偏好圓餅圖`
    : `🥧 活動性質偏好圓餅圖 (全社心願比例)`;

  const rankingSectionTitle = isMemberMode
    ? `🏆 社員「${targetMember.name}」心願活動清單`
    : `🏆 全社想參加活動排行榜`;

  const rankingSectionSub = isMemberMode
    ? `(共 ${rankedActivities.length} 項活動 · 依全社熱門度排序 · 點擊直接開啟預覽)`
    : `(由高到低排序 · 點擊直接開啟企劃預覽與切換)`;

  container.innerHTML = `
    <!-- 雙圖表儀表板 (長條圖 & 圓餅圖) -->
    <div class="charts-grid">
      <!-- 長條圖：熱門得票排行 -->
      <div class="chart-box">
        <div class="chart-title">
          <span>${barChartTitle}</span>
        </div>
        <div style="margin-top: 10px;">
          ${barChartDisplayItems.length === 0 ? '<div style="text-align:center; color:#94a3b8; padding: 20px;">無心願活動</div>' : barChartDisplayItems.map(item => {
            const pct = Math.round((item.count / memberVotes.length) * 100);
            return `
              <div class="bar-row" onclick="openDetailModalById('${item.id}', 'ranked')" style="cursor: pointer;" title="點擊預覽此企劃">
                <span class="bar-label" title="${item.act.title}">${item.act.title}</span>
                <div class="bar-track">
                  <div class="bar-fill" style="width: ${pct}%;"></div>
                </div>
                <span class="bar-value"><span class="bar-vote-num">${item.count} 票</span><span class="bar-pct">(${pct}%)</span></span>
              </div>
            `;
          }).join('')}
        </div>
      </div>

      <!-- 圓餅圖：活動類型偏好佔比 (休閒 vs 競技 vs 手作) -->
      <div class="chart-box">
        <div class="chart-title">
          <span>${pieChartTitle}</span>
        </div>
        <div style="display: flex; align-items: center; justify-content: space-around; gap: 20px; flex-wrap: wrap;">
          ${pieSVG}
          <div style="display: flex; flex-direction: column; gap: 8px; font-size: 0.85rem;">
            <div style="display: flex; align-items: center; gap: 8px;">
              <span style="display: inline-block; width: 12px; height: 12px; background: #818cf8; border-radius: 3px;"></span>
              <span>☕ 休閒：<strong>${displayTypeCounts.casual} ${isMemberMode ? '項' : '票'}</strong></span>
            </div>
            <div style="display: flex; align-items: center; gap: 8px;">
              <span style="display: inline-block; width: 12px; height: 12px; background: #f59e0b; border-radius: 3px;"></span>
              <span>🏆 競技：<strong>${displayTypeCounts.score} ${isMemberMode ? '項' : '票'}</strong></span>
            </div>
            <div style="display: flex; align-items: center; gap: 8px;">
              <span style="display: inline-block; width: 12px; height: 12px; background: #ec4899; border-radius: 3px;"></span>
              <span>✂️ 手作：<strong>${displayTypeCounts.craft} ${isMemberMode ? '項' : '票'}</strong></span>
            </div>
          </div>
        </div>
      </div>
    </div>

    <!-- 概覽看板 (前三項指標同高同排，第四項大卡置底) -->
    <div class="stats-overview-grid">
      <div class="stats-metrics-trio">
        ${statCard1}
        ${statCard2}
        ${statCard3}
      </div>
      ${statCard4}
    </div>

    <!-- 活動總統計清單 (由高到低排序，僅顯示標題，點擊預覽) -->
    <div class="stats-card-panel">
      <div class="stats-card-header">
        <h3>
          <span>${rankingSectionTitle}</span>
          <span style="font-size: 0.85rem; color: #94a3b8; font-weight: normal;">${rankingSectionSub}</span>
        </h3>
        <span style="font-size: 0.85rem; color: #10b981;">共 ${rankedActivities.length} 項企劃</span>
      </div>

      <div class="ranking-list">
        ${rankedActivities.length === 0 ? '<div style="text-align:center; color:#94a3b8; padding: 24px;">暫無活動項目</div>' : rankedActivities.map((item, idx) => {
          let rankBadge = `${idx + 1}`;
          if (idx === 0) rankBadge = '🥇 1';
          else if (idx === 1) rankBadge = '🥈 2';
          else if (idx === 2) rankBadge = '🥉 3';

          return `
            <div class="ranking-item" onclick="openDetailModalById('${item.id}', 'ranked')" title="點擊預覽「${item.act.title}」完整企劃書">
              <div class="ranking-badge">${rankBadge}</div>
              <div class="ranking-title">${item.act.title}</div>
              <span class="badge-category" style="font-size: 0.72rem; padding: 2px 6px;">${item.act.category}</span>
              <span class="badge-subtype badge-${item.act.subTypeKey}" style="font-size: 0.72rem; padding: 2px 6px;">${item.act.subType || ''}</span>
              <div class="ranking-votes">🔥 ${item.count} 票</div>
            </div>
          `;
        }).join('')}
      </div>
    </div>

    <!-- 已匯入社員卡片清單 (以方框為單位的欄位) -->
    <div class="stats-card-panel">
      <div class="stats-card-header">
        <h3>
          <span>👥 已匯入社員心願卡盒</span>
          <span style="font-size: 0.85rem; color: #94a3b8; font-weight: normal;">(點擊「總票數」可直接在上方圖表中篩選該社員，點擊活動可預覽)</span>
        </h3>
        <span style="font-size: 0.85rem; color: #cbd5e1;">共 ${memberVotes.length} 份紀錄</span>
      </div>

      <div class="member-boxes-grid">
        ${memberVotes.map(vote => {
          const isSelected = isMemberMode && vote.id === targetMember.id;
          const acts = (vote.selectedIds || []).map(id => activitiesData.find(a => a.id === id)).filter(Boolean);
          return `
            <div class="member-box-card ${isSelected ? 'is-selected' : ''}">
              <div class="member-box-header">
                <div class="member-name">
                  <span>👤 ${vote.name}</span>
                  ${isSelected ? '<span class="member-badge-active">圖表顯示中</span>' : ''}
                </div>
                <div style="display: flex; align-items: center; gap: 8px;">
                  <button class="btn-filter-member-card ${isSelected ? 'active' : ''}" onclick="filterByMember('${vote.id}')" title="點擊在上方圖表中顯示社員「${vote.name}」的心願活動">
                    <svg class="mono-icon" viewBox="0 0 24 24" width="12" height="12" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
                      <line x1="18" y1="20" x2="18" y2="10"></line>
                      <line x1="12" y1="20" x2="12" y2="4"></line>
                      <line x1="6" y1="20" x2="6" y2="14"></line>
                    </svg>
                    <span>總票數: ${acts.length} 票</span>
                  </button>
                  <button onclick="deleteMemberVote('${vote.id}')" style="background: transparent; border: none; color: #ef4444; cursor: pointer; font-size: 0.9rem; padding: 2px 4px;" title="刪除此紀錄">✕</button>
                </div>
              </div>
              <div style="font-size: 0.75rem; color: var(--text-muted);">匯入時間：${vote.time}</div>

              <!-- 底下顯示該社員選擇的活動內容 -->
              <div class="member-activities-list">
                ${acts.map(act => `
                  <div class="member-activity-chip" onclick="openDetailModalById('${act.id}', 'member-${vote.id}')" title="點擊預覽此活動">
                    <span style="white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 220px;">${act.title}</span>
                    <span style="font-size: 0.7rem; color: var(--text-dim);">${act.subType || ''}</span>
                  </div>
                `).join('')}
              </div>
            </div>
          `;
        }).join('')}
      </div>
    </div>
  `;
  renderMemberQuickFilterChips();
}

// 產生 SVG 圓餅環形圖
function createDonutChartSVG(typeCounts) {
  const total = (typeCounts.casual + typeCounts.score + typeCounts.craft) || 1;
  const pCasual = typeCounts.casual / total;
  const pScore = typeCounts.score / total;
  const pCraft = typeCounts.craft / total;

  const r = 40;
  const c = 2 * Math.PI * r;

  const dashCasual = (pCasual * c).toFixed(1);
  const dashScore = (pScore * c).toFixed(1);
  const dashCraft = (pCraft * c).toFixed(1);

  const offsetScore = (-(pCasual * c)).toFixed(1);
  const offsetCraft = (-((pCasual + pScore) * c)).toFixed(1);

  return `
    <svg width="120" height="120" viewBox="0 0 100 100" style="transform: rotate(-90deg);">
      <circle cx="50" cy="50" r="${r}" fill="transparent" class="donut-track" stroke-width="18" />
      <circle cx="50" cy="50" r="${r}" fill="transparent" stroke="#818cf8" stroke-width="18" stroke-dasharray="${dashCasual} ${c}" stroke-dashoffset="0" />
      <circle cx="50" cy="50" r="${r}" fill="transparent" stroke="#f59e0b" stroke-width="18" stroke-dasharray="${dashScore} ${c}" stroke-dashoffset="${offsetScore}" />
      <circle cx="50" cy="50" r="${r}" fill="transparent" stroke="#ec4899" stroke-width="18" stroke-dasharray="${dashCraft} ${c}" stroke-dashoffset="${offsetCraft}" />
    </svg>
  `;
}

// 動態計算各子類型標籤數量 (社員匯入內容不計入喜好，除非點開該社員的篩選內容)
function updateSubTypeBadges() {
  let baseList = activitiesData;

  // 關鍵：若點開了社員篩選內容，基底池先限制為該社員所選的心願活動
  if (activeMemberFilter) {
    const vote = memberVotes.find(v => v.id === activeMemberFilter);
    if (vote && Array.isArray(vote.selectedIds)) {
      baseList = activitiesData.filter(a => vote.selectedIds.includes(a.id));
    }
  }

  if (currentCategory === 'favorites') {
    // 喜好分類：嚴格只計算本人喜好（若在社員篩選下，則計算該社員選取中屬於本人喜好的項目）
    if (favoritesSessionPool) {
      baseList = baseList.filter(a => favoritesSessionPool.has(a.id));
    } else {
      baseList = baseList.filter(a => favoriteIds.has(a.id));
    }
  } else if (currentCategory === 'hsr') {
    baseList = baseList.filter(a => a.categoryKey === 'hsr');
  } else if (currentCategory === 'genshin') {
    baseList = baseList.filter(a => a.categoryKey === 'genshin');
  } else if (currentCategory === 'zzz') {
    baseList = baseList.filter(a => a.categoryKey === 'zzz');
  }

  const badgeAll = document.getElementById('badgeAll');
  const badgeCasual = document.getElementById('badgeCasual');
  const badgeScore = document.getElementById('badgeScore');
  const badgeCraft = document.getElementById('badgeCraft');

  if (badgeAll) badgeAll.textContent = baseList.length;
  if (badgeCasual) badgeCasual.textContent = baseList.filter(a => a.subTypeKey === 'casual').length;
  if (badgeScore) badgeScore.textContent = baseList.filter(a => a.subTypeKey === 'score').length;
  if (badgeCraft) badgeCraft.textContent = baseList.filter(a => a.subTypeKey === 'craft').length;
}

// 取得篩選後的清單 (社員匯入內容不計入喜好，除非點開該社員的篩選內容)
function getFilteredActivities() {
  let filtered = activitiesData.filter(act => {
    // 關鍵 1：若點開了該社員的篩選內容，先以該社員勾選的項目為準
    if (activeMemberFilter) {
      const vote = memberVotes.find(v => v.id === activeMemberFilter);
      if (vote && Array.isArray(vote.selectedIds)) {
        if (!vote.selectedIds.includes(act.id)) return false;
      }
    }

    // 關鍵 2：大分類過濾 (若在喜好分類，只比對本人喜好 favoriteIds)
    let matchCat = false;
    if (currentCategory === 'all' || currentCategory === 'stats') {
      matchCat = true;
    } else if (currentCategory === 'favorites') {
      if (favoritesSessionPool) {
        matchCat = favoritesSessionPool.has(act.id);
      } else {
        matchCat = favoriteIds.has(act.id);
      }
    } else {
      matchCat = (act.categoryKey === currentCategory);
    }

    let matchSub = false;
    if (currentSubType === 'all') {
      matchSub = true;
    } else {
      matchSub = (act.subTypeKey === currentSubType);
    }

    if (!matchCat || !matchSub) return false;
    if (!searchQuery) return true;

    const userNote = activityNotes[act.id] || '';
    const fullText = [
      act.title,
      act.subtitle,
      act.category,
      act.subType || '',
      act.summary,
      act.targetAudience || '',
      act.highlights || '',
      userNote
    ].join(' ').toLowerCase();

    return fullText.includes(searchQuery.toLowerCase());
  });

  // 在「喜歡」分類下，若有取消標記的項目，預設排在最前面
  if (currentCategory === 'favorites' && favoritesUnmarkedList.length > 0) {
    const unmarkedSet = new Set(favoritesUnmarkedList);
    const unmarkedCards = [];
    favoritesUnmarkedList.forEach(unmarkedId => {
      const found = filtered.find(a => a.id === unmarkedId);
      if (found) unmarkedCards.push(found);
    });

    const remainingCards = filtered.filter(a => !unmarkedSet.has(a.id));
    filtered = [...unmarkedCards, ...remainingCards];
  }

  return filtered;
}

// 渲染便利貼卡盒網格
function renderCards() {
  const container = document.getElementById('cardsContainer');
  if (!container) return;

  const filtered = getFilteredActivities();

  // 更新當前預設切換池為篩選結果
  currentModalContextPool = filtered;

  if (filtered.length === 0) {
    if (currentCategory === 'favorites') {
      if (favoriteIds.size === 0) {
        container.innerHTML = `
          <div class="empty-state">
            <div class="empty-state-icon">❤️</div>
            <h3>尚未收藏任何活動企劃</h3>
            <p>您目前還沒有標註任何喜好企劃。點擊卡片右上角的書籤圖示即可加入喜好清單！</p>
          </div>
        `;
      } else {
        const subTypeName = {
          'casual': '休閒',
          'score': '競技',
          'craft': '手作'
        }[currentSubType] || '當前性質分類';

        container.innerHTML = `
          <div class="empty-state">
            <div class="empty-state-icon">🏷️</div>
            <h3>在「${subTypeName}」中尚無標記喜歡的企劃</h3>
            <p>您已收藏標記了 <strong style="color: #f43f5e; font-size: 1.15rem;">${favoriteIds.size}</strong> 份喜歡的企劃，但目前選取的分類中無符合項目。</p>
            <button class="btn-action" onclick="switchToAllSubTypes()" style="margin-top: 16px; background: linear-gradient(135deg, #f43f5e, #fb7185); color: #fff; font-weight: 700; padding: 10px 24px; border-radius: 999px; box-shadow: 0 4px 15px rgba(244, 63, 94, 0.4); border: none; cursor: pointer; display: inline-flex; align-items: center; gap: 8px;">
              <span>👉 查看全部已標記喜歡的企劃 (${favoriteIds.size} 份)</span>
            </button>
          </div>
        `;
      }
    } else {
      container.innerHTML = `
        <div class="empty-state">
          <div class="empty-state-icon">🔍</div>
          <h3>沒有找到相符的活動企劃</h3>
          <p>請嘗試更換篩選條件或輸入不同的關鍵字搜尋。</p>
          <button class="btn-action" onclick="resetAllFilters()" style="margin-top: 14px;">🔄 重設篩選條件</button>
        </div>
      `;
    }
    return;
  }

  container.innerHTML = filtered.map(act => createCardHTML(act)).join('');
  container.classList.toggle('cards-collapsed', isCardsCollapsed);
  updateExpandToggleButtons();

  // 綁定手風琴展開收起
  container.querySelectorAll('.accordion-toggle').forEach(btn => {
    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      const item = btn.closest('.accordion-item');
      item.classList.toggle('open');
    });
  });

  // 綁定書籤收藏/選取點擊
  container.querySelectorAll('.btn-bookmark-toggle').forEach(btn => {
    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      const id = btn.dataset.id;
      toggleUnifiedBookmark(id);
    });
  });

  // 綁定查看完整企劃彈窗
  container.querySelectorAll('.btn-card-detail').forEach(btn => {
    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      const id = btn.dataset.id;
      openDetailModalById(id, 'cards');
    });
  });

  // 綁定卡片點擊開啟彈窗 (嚴格防冒泡)
  container.querySelectorAll('.postit-card').forEach(card => {
    card.addEventListener('click', (e) => {
      if (e.target.closest('button') || e.target.closest('a') || e.target.closest('.accordion-toggle') || e.target.closest('.btn-bookmark-toggle') || e.target.closest('input')) {
        return;
      }
      const id = card.id.replace('card-', '');
      openDetailModalById(id, 'cards');
    });
  });

  // 綁定複製摘要按鈕
  container.querySelectorAll('.btn-copy-card').forEach(btn => {
    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      const id = btn.dataset.id;
      const act = activitiesData.find(a => a.id === id);
      if (act) copyActivitySummary(act);
    });
  });

  // 渲染位於統計圖表卡片內的社員快速篩選按鈕
  renderMemberQuickFilterChips();
}

// 產生單張卡片 HTML (融合愛心與選取為右上角圖二書籤圖標)
function createCardHTML(act) {
  const isMarked = favoriteIds.has(act.id);
  const status = activityStatuses[act.id] || 'none';
  const hasNote = Boolean(activityNotes[act.id]);

  let statusBadgeHTML = '';
  if (status === 'wish') {
    statusBadgeHTML = `<span class="badge-status badge-wish" title="標記為想參加"><span class="status-dot dot-wish"></span>想參加</span>`;
  } else if (status === 'planned') {
    statusBadgeHTML = `<span class="badge-status badge-planned" title="標記為籌備中"><span class="status-dot dot-planned"></span>籌備中</span>`;
  } else if (status === 'completed') {
    statusBadgeHTML = `<span class="badge-status badge-completed" title="標記為已舉辦"><span class="status-dot dot-completed"></span>已舉辦</span>`;
  }

  const noteBadgeHTML = hasNote ? `<span class="badge-note-tag" title="有自訂幹部備忘筆記"><svg class="mono-icon" viewBox="0 0 24 24" width="12" height="12" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"></path><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"></path></svg> 備忘</span>` : '';

  const notesList = (act.extraNotes || []).map(note => `<li>${note}</li>`).join('');

  const scheduleRows = (act.schedule || []).map(s => `
    <div class="schedule-row">
      <span class="schedule-time">${s.time}</span>
      <span class="schedule-item">${s.item}</span>
    </div>
  `).join('');

  const supplyPills = (act.supplies || []).map(sup => `
    <span class="supply-tag">${sup}</span>
  `).join('');

  return `
    <article class="postit-card card-${act.subTypeKey || 'casual'} card-cat-${act.categoryKey || 'other'}" id="card-${act.id}">
      <div class="card-header">
        <div class="card-badges-left">
          <span class="badge-category">${act.category}</span>
          <span class="badge-subtype badge-${act.subTypeKey}">${act.subType || ''}</span>
          ${statusBadgeHTML}
          ${noteBadgeHTML}
        </div>
        <!-- 融合愛心與選取之書籤按鈕 (未選取=空心，選取=實心，完全比照附圖) -->
        <button 
          class="btn-bookmark-toggle ${isMarked ? 'active' : ''}" 
          data-id="${act.id}" 
          type="button" 
          title="${isMarked ? '已選取 (點擊取消)' : '未選取 (點擊選取)'}"
        >
          ${getBookmarkSVG(isMarked)}
        </button>
      </div>

      <div class="card-body">
        <h3 class="card-title">${act.title}</h3>
        <p class="card-subtitle">${act.subtitle}</p>

        <div class="card-summary">
          ${act.summary}
        </div>

        <div class="card-meta-list">
          <div><strong>規模：</strong>${act.participants}</div>
          <div><strong>時長：</strong>${act.duration}</div>
          <div><strong>地點：</strong>${act.location}</div>
          <div><strong>亮點：</strong>${act.highlight}</div>
        </div>

        <!-- 便利貼收合手風琴區塊 -->
        <div class="accordion-container">
          <div class="accordion-item">
            <button class="accordion-toggle" type="button">
              <span class="accordion-toggle-title">
                <svg class="mono-icon" viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><line x1="12" y1="17" x2="12" y2="22"></line><path d="M5 17h14v-1.76a2 2 0 0 0-1.11-1.79l-1.78-.9A2 2 0 0 1 15 10.76V6h1a2 2 0 0 0 0-4H8a2 2 0 0 0 0 4h1v4.76a2 2 0 0 1-1.11 1.79l-1.78.9A2 2 0 0 0 5 15.24Z"></path></svg>
                <span>額外附註與備註 (${(act.extraNotes || []).length} 條)</span>
              </span>
              <svg class="accordion-arrow" viewBox="0 0 24 24" width="12" height="12" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"></polyline></svg>
            </button>
            <div class="accordion-content">
              <ul class="notes-list">${notesList}</ul>
            </div>
          </div>

          <div class="accordion-item">
            <button class="accordion-toggle" type="button">
              <span class="accordion-toggle-title">
                <svg class="mono-icon" viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="4" width="18" height="18" rx="2" ry="2"></rect><line x1="16" y1="2" x2="16" y2="6"></line><line x1="8" y1="2" x2="8" y2="6"></line><line x1="3" y1="10" x2="21" y2="10"></line></svg>
                <span>活動時程安排 (${(act.schedule || []).length} 階段)</span>
              </span>
              <svg class="accordion-arrow" viewBox="0 0 24 24" width="12" height="12" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"></polyline></svg>
            </button>
            <div class="accordion-content">
              <div class="schedule-list">${scheduleRows}</div>
            </div>
          </div>

          <div class="accordion-item">
            <button class="accordion-toggle" type="button">
              <span class="accordion-toggle-title">
                <svg class="mono-icon" viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 16V8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16z"></path><polyline points="3.27 6.96 12 12.01 20.73 6.96"></polyline><line x1="12" y1="22.08" x2="12" y2="12"></line></svg>
                <span>物資清單與預算預估</span>
              </span>
              <svg class="accordion-arrow" viewBox="0 0 24 24" width="12" height="12" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"></polyline></svg>
            </button>
            <div class="accordion-content">
              <p style="margin-bottom: 6px; color: var(--color-score); font-weight: 600;">預估預算：${act.budget}</p>
              <div class="tag-pills-wrap">${supplyPills}</div>
            </div>
          </div>
        </div>
      </div>

      <div class="card-footer">
        <button class="btn-card-detail" data-id="${act.id}" type="button">
          <svg class="mono-icon" viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M2 3h6a4 4 0 0 1 4 4v14a3 3 0 0 0-3-3H2z"></path><path d="M22 3h-6a4 4 0 0 0-4 4v14a3 3 0 0 1 3-3h7z"></path></svg>
          <span>查看完整企劃書</span>
        </button>
        <button class="btn-copy-card" data-id="${act.id}" title="複製企劃摘要發給幹部群" type="button">
          <svg class="mono-icon" viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><rect x="9" y="9" width="13" height="13" rx="2" ry="2"></rect><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"></path></svg>
        </button>
      </div>
    </article>
  `;
}

// ==========================================================================
// 3. 活動詳細 Modal 彈窗與自適應前後切換 (Navigation Engine)
// ==========================================================================
function openDetailModalById(id, contextSource) {
  const act = activitiesData.find(a => a.id === id);
  if (!act) return;

  // 自適應上下文池更新
  if (contextSource === 'cards') {
    currentModalContextPool = getFilteredActivities();
  } else if (contextSource === 'ranked') {
    // 依排行榜順序
    const voteCounts = {};
    memberVotes.forEach(v => (v.selectedIds || []).forEach(x => voteCounts[x] = (voteCounts[x] || 0) + 1));
    currentModalContextPool = Object.keys(voteCounts)
      .map(k => activitiesData.find(a => a.id === k))
      .filter(Boolean)
      .sort((a, b) => (voteCounts[b.id] || 0) - (voteCounts[a.id] || 0));
  } else if (contextSource && contextSource.startsWith('member-')) {
    const memberId = contextSource.replace('member-', '');
    const vote = memberVotes.find(v => v.id === memberId);
    if (vote) {
      currentModalContextPool = (vote.selectedIds || []).map(x => activitiesData.find(a => a.id === x)).filter(Boolean);
    }
  }

  if (!currentModalContextPool || currentModalContextPool.length === 0) {
    currentModalContextPool = activitiesData;
  }

  openDetailModal(act);
}

// 切換至上一項活動
function navigatePrevActivity() {
  if (!currentModalActId) return;
  const pool = (currentModalContextPool && currentModalContextPool.length > 0) ? currentModalContextPool : activitiesData;
  const idx = pool.findIndex(a => a.id === currentModalActId);
  if (idx > 0) {
    openDetailModal(pool[idx - 1]);
  } else {
    openDetailModal(pool[pool.length - 1]);
  }
}

// 切換至下一項活動
function navigateNextActivity() {
  if (!currentModalActId) return;
  const pool = (currentModalContextPool && currentModalContextPool.length > 0) ? currentModalContextPool : activitiesData;
  const idx = pool.findIndex(a => a.id === currentModalActId);
  if (idx >= 0 && idx < pool.length - 1) {
    openDetailModal(pool[idx + 1]);
  } else {
    openDetailModal(pool[0]);
  }
}

// 更新 Modal 彈窗內的書籤選取按鈕樣式
function updateModalFavBtn(id) {
  if (currentModalActId !== id) return;
  const isMarked = favoriteIds.has(id);
  const modalFavBtn = document.getElementById('modalFavBtn');
  if (modalFavBtn) {
    modalFavBtn.classList.toggle('active', isMarked);
    modalFavBtn.innerHTML = isMarked 
      ? `<svg class="mono-icon" viewBox="0 0 24 24" width="15" height="15" fill="#f43f5e" stroke="#f43f5e" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M19 21l-7-5-7 5V5a2 2 0 0 1 2-2h10a2 2 0 0 1 2 2z"></path></svg><span>已標記喜歡</span>` 
      : `<svg class="mono-icon" viewBox="0 0 24 24" width="15" height="15" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M19 21l-7-5-7 5V5a2 2 0 0 1 2-2h10a2 2 0 0 1 2 2z"></path></svg><span>標記喜歡</span>`;
  }
  const modalBookmarkBtnText = document.getElementById('modalBookmarkBtnText');
  if (modalBookmarkBtnText) {
    modalBookmarkBtnText.textContent = isMarked ? '已標記為喜歡' : '標記此活動為喜歡';
  }
  const modalBookmarkIcon = document.getElementById('modalBookmarkIcon');
  if (modalBookmarkIcon) {
    modalBookmarkIcon.innerHTML = getBookmarkSVG(isMarked);
  }
  const modalBookmarkBtnWrap = document.getElementById('modalBookmarkBtnWrap');
  if (modalBookmarkBtnWrap) {
    modalBookmarkBtnWrap.classList.toggle('active', isMarked);
  }
}

// 更新 Modal 內的狀態按鈕樣式
function updateModalStatusControls(actId) {
  if (currentModalActId !== actId) return;
  const currentStatus = activityStatuses[actId] || 'none';
  document.querySelectorAll('.btn-status-toggle').forEach(btn => {
    btn.classList.toggle('active', btn.dataset.status === currentStatus);
  });
}

// 開啟詳細 Modal 彈窗
function openDetailModal(act) {
  currentModalActId = act.id;
  const modal = document.getElementById('modalBackdrop');
  const modalTitle = document.getElementById('modalTitle');
  const modalSubtitleText = document.getElementById('modalSubtitleText');
  const modalNavCounter = document.getElementById('modalNavCounter');
  const modalBody = document.getElementById('modalBody');

  if (modalTitle) modalTitle.textContent = act.title;
  if (modalSubtitleText) modalSubtitleText.textContent = `${act.category} · ${act.subType || ''} | ${act.subtitle}`;

  // 更新進度計數器
  const pool = (currentModalContextPool && currentModalContextPool.length > 0) ? currentModalContextPool : activitiesData;
  const curIdx = pool.findIndex(a => a.id === act.id);
  if (modalNavCounter) {
    if (curIdx >= 0) {
      modalNavCounter.textContent = `(${curIdx + 1} / ${pool.length})`;
    } else {
      modalNavCounter.textContent = `(1 / ${pool.length})`;
    }
  }

  const scheduleHTML = (act.schedule || []).map(s => `
    <div class="schedule-item">
      <strong class="schedule-time">${s.time}</strong>
      <span class="schedule-desc">${s.item}</span>
    </div>
  `).join('');

  const notesHTML = (act.extraNotes || []).map(n => `<li>${n}</li>`).join('');
  const suppliesHTML = (act.supplies || []).map(s => `<li>${s}</li>`).join('');
  
  const currentStatus = activityStatuses[act.id] || 'none';
  const savedNote = activityNotes[act.id] || '';
  const isSelected = favoriteIds.has(act.id);

  modalBody.innerHTML = `
    <!-- 本機狀態追蹤與喜歡標記 (LocalStorage) -->
    <div class="modal-prep-card">
      <div class="modal-prep-header">
        <div class="modal-prep-title">活動籌備與喜歡標記 (本機自動儲存)</div>
        <div style="display: flex; align-items: center; gap: 8px;">
          <!-- 彈窗內快速標記喜歡 (未標記=空心，已標記=實心) -->
          <button 
            type="button" 
            id="modalBookmarkBtnWrap"
            class="btn-action btn-modal-bookmark-toggle ${isSelected ? 'active' : ''}" 
            onclick="toggleUnifiedBookmark('${act.id}')"
          >
            <span id="modalBookmarkIcon" style="display: inline-flex; align-items: center;">${getBookmarkSVG(isSelected)}</span>
            <span id="modalBookmarkBtnText">${isSelected ? '已標記為喜歡' : '標記此活動為喜歡'}</span>
          </button>
          <span class="modal-prep-sync">自動同步</span>
        </div>
      </div>
      
      <div class="status-btn-group">
        <button type="button" class="btn-status-toggle ${currentStatus === 'none' ? 'active' : ''}" data-status="none"><span class="status-dot"></span>未安排</button>
        <button type="button" class="btn-status-toggle ${currentStatus === 'wish' ? 'active' : ''}" data-status="wish"><span class="status-dot dot-wish"></span>想參加</button>
        <button type="button" class="btn-status-toggle ${currentStatus === 'planned' ? 'active' : ''}" data-status="planned"><span class="status-dot dot-planned"></span>籌備中</button>
        <button type="button" class="btn-status-toggle ${currentStatus === 'completed' ? 'active' : ''}" data-status="completed"><span class="status-dot dot-completed"></span>已舉辦</button>
      </div>

      <div class="modal-note-wrap">
        <label for="actPersonalNote" class="modal-note-label">
          幹部 / 個人私房備忘錄：
        </label>
        <textarea 
          id="actPersonalNote" 
          rows="2" 
          placeholder="例如：預計第6週週五舉辦、請副社長向學校借投影機、預計點5份韓式炸雞...（輸入即刻自動儲存）"
          class="modal-note-textarea"
        >${savedNote}</textarea>
        <div id="noteSaveStatus" class="modal-note-status">
          ${savedNote ? '✅ 備忘內容已存於本機' : '💡 輸入任何內容均會自動儲存於本機瀏覽器'}
        </div>
      </div>
    </div>

    <div class="modal-section">
      <div class="modal-section-title">活動基本資訊</div>
      <div class="modal-info-grid">
        <div><strong>人數規模：</strong>${act.participants}</div>
        <div><strong>預估耗時：</strong>${act.duration}</div>
        <div><strong>建議地點：</strong>${act.location}</div>
        <div><strong>預算預估：</strong>${act.budget}</div>
      </div>
    </div>

    <div class="modal-section">
      <div class="modal-section-title">企劃目標與核心概念</div>
      <p style="color: var(--text-secondary); font-size: 0.95rem; line-height: 1.6;">${act.summary}</p>
      <div class="modal-highlight-box">
        <strong>特色亮點：</strong>${act.highlight}
      </div>
    </div>

    <div class="modal-section">
      <div class="modal-section-title">完整活動時程表</div>
      <div>${scheduleHTML}</div>
    </div>

    <div class="modal-section">
      <div class="modal-section-title">規則公約與注意事項</div>
      <pre class="modal-rules-box">${act.rules}</pre>
    </div>

    <div class="modal-section">
      <div class="modal-section-title">必備物資與器材清單</div>
      <ul class="modal-supplies-list">${suppliesHTML}</ul>
    </div>

    <div class="modal-section">
      <div class="modal-section-title">幹部專用額外附註與備註說明</div>
      <ul class="modal-notes-list">${notesHTML}</ul>
    </div>

    <!-- 三位社員交叉對比點評區塊 -->
    <div class="modal-section">
      <div class="modal-section-title">三位社員交叉對比點評與審查反饋</div>
      <div class="modal-reviews-box">
        <div class="review-item review-item-tie">
          <strong>阿鐵 (硬核深淵技術黨)：</strong>
          <span>
            ${((act.subType === '競技' || act.subType === '衝分')) ? '⭐⭐⭐⭐⭐【本命戰場】極限壓輪、無傷走位與四星逆襲最考驗實力，規則公平且充滿熱血！' :
              (act.subType === '休閒') ? '【精神回血】不拼極限數值，大家同屏抽卡開盲盒氣氛極好，深淵打累後的最佳放鬆！' :
              '【手殘救星】原以為手殘做不出來，但配備預製模具與速乾燈，連我這種只會按鍵盤的人都能一次成功！'}
          </span>
        </div>
        <div class="review-item review-item-you">
          <strong>悠悠 (佛系休閒氛圍黨)：</strong>
          <span>
            ${(act.subType === '休閒') ? '⭐⭐⭐⭐⭐【滿分推薦】徹底告別劇本殺與上台簡報！零社恐、零尷尬，喝奶茶吃炸雞聊天超快樂！' :
              ((act.subType === '競技' || act.subType === '衝分')) ? '【被照顧到了】不用擔心自己練度不夠，現場設有觀戰競猜席與雙人手把賽，看神仙打架也超爽！' :
              '【超級治癒】邊播原聲帶音樂邊動手捏周邊，完成後拍照發限動超級吸睛，完全沒時間壓力！'}
          </span>
        </div>
        <div class="review-item review-item-qi">
          <strong>奇奇 (文創手作生活黨)：</strong>
          <span>
            ${((act.subType === '手作' || act.subType === '動手製作')) ? '⭐⭐⭐⭐⭐【文創核心】無毒材料、嚴格控制在 90 分鐘內完工，100% 把精緻實體周邊帶回家！' :
              (act.subType === '休閒') ? '【儀式感拉滿】零食盲測評分與盲盒互換很有社交溫度，拍照紀錄發社刊超級好看！' :
              '【榮譽感滿分】賽後頒發手作專屬壓克力獎牌，並設有「手殘抽象搞笑獎」，人人有獎！'}
          </span>
        </div>
      </div>
    </div>
  `;

  modalBody.querySelectorAll('.btn-status-toggle').forEach(btn => {
    btn.addEventListener('click', () => {
      const targetStatus = btn.dataset.status;
      setActivityStatus(act.id, targetStatus);
    });
  });

  const noteArea = document.getElementById('actPersonalNote');
  const noteStatus = document.getElementById('noteSaveStatus');
  if (noteArea) {
    let debounceTimer = null;
    noteArea.addEventListener('input', (e) => {
      if (noteStatus) noteStatus.textContent = '⏳ 正在自動儲存...';
      clearTimeout(debounceTimer);
      debounceTimer = setTimeout(() => {
        saveActivityNote(act.id, e.target.value);
        if (noteStatus) noteStatus.textContent = '✅ 已即時儲存至本機！';
      }, 400);
    });
  }

  const modalFavBtn = document.getElementById('modalFavBtn');
  if (modalFavBtn) {
    updateModalFavBtn(act.id);
    modalFavBtn.onclick = () => {
      toggleFavorite(act.id);
    };
  }

  const modalCopyBtn = document.getElementById('modalCopyBtn');
  if (modalCopyBtn) {
    modalCopyBtn.onclick = () => copyFullActivityPlan(act);
  }

  modal.classList.add('active');
  document.body.style.overflow = 'hidden';
}

function closeModal() {
  const modal = document.getElementById('modalBackdrop');
  if (modal) modal.classList.remove('active');
  document.body.style.overflow = '';
  currentModalActId = null;
}

// 命運抽卡！
function triggerGachaDraw() {
  const gachaOverlay = document.getElementById('gachaOverlay');
  const gachaResultText = document.getElementById('gachaResultText');
  const gachaResultDetail = document.getElementById('gachaResultDetail');

  if (!gachaOverlay) return;

  const currentPool = getFilteredActivities();
  const targetPool = currentPool.length > 0 ? currentPool : activitiesData;

  gachaOverlay.classList.add('active');
  gachaResultText.textContent = "祈願連線中...命運星軌轉動中！⭐";
  gachaResultDetail.textContent = `正在從當前 ${targetPool.length} 份企劃中抽出最佳活動...`;

  setTimeout(() => {
    const randomAct = targetPool[Math.floor(Math.random() * targetPool.length)];
    
    gachaHistory.unshift({
      id: randomAct.id,
      title: randomAct.title,
      time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      category: randomAct.category
    });
    if (gachaHistory.length > 10) gachaHistory.pop();
    try {
      localStorage.setItem(STORAGE_KEYS.GACHA_HISTORY, JSON.stringify(gachaHistory));
    } catch (e) {}

    gachaResultText.textContent = `🎉 恭喜抽出：${randomAct.title}！`;
    gachaResultDetail.innerHTML = `
      <div style="font-size: 1.1rem; color: #f59e0b; margin-top: 8px; font-weight: bold;">
        【${randomAct.category} · ${randomAct.subType || ''}】${randomAct.subtitle}
      </div>
      <p style="margin-top: 10px; color: #e2e8f0;">${randomAct.summary}</p>
      <div style="margin-top: 20px;">
        <button class="btn-action" id="btnGoToRandomCard" style="background: linear-gradient(135deg, #f59e0b, #ef4444); color: #fff; font-weight: bold; padding: 10px 24px;">
          👉 立即查看這份企劃
        </button>
        <button class="btn-action" id="btnCloseGacha" style="margin-left: 10px; padding: 10px 18px;">
          關閉
        </button>
      </div>
    `;

    document.getElementById('btnCloseGacha').onclick = () => {
      gachaOverlay.classList.remove('active');
    };

    document.getElementById('btnGoToRandomCard').onclick = () => {
      gachaOverlay.classList.remove('active');
      openDetailModalById(randomAct.id, 'gacha');
      const targetCard = document.getElementById(`card-${randomAct.id}`);
      if (targetCard) {
        targetCard.scrollIntoView({ behavior: 'smooth', block: 'center' });
        targetCard.style.outline = '3px solid #f59e0b';
        setTimeout(() => targetCard.style.outline = '', 3000);
      }
    };
  }, 1200);
}

// 複製企劃摘要
function copyActivitySummary(act) {
  const isFavText = favoriteIds.has(act.id) ? " (已標註喜好 ❤️)" : "";
  const status = activityStatuses[act.id] ? ` [狀態: ${activityStatuses[act.id]}]` : "";
  const text = `【北商米遊同好會活動企劃】${act.title}${isFavText}${status}\n分類：${act.category} (${act.subType || ''})\n人數：${act.participants} | 預計時間：${act.duration}\n地點：${act.location}\n亮點：${act.highlight}\n介紹：${act.summary}`;
  navigator.clipboard.writeText(text).then(() => {
    showToast(`已成功複製「${act.title}」活動摘要！`);
  });
}

// 複製完整企劃 Markdown
function copyFullActivityPlan(act) {
  const statusLabel = {
    'wish': '想參加 🙋',
    'planned': '籌備中 📝',
    'completed': '已舉辦 ✅',
    'none': '未安排'
  }[activityStatuses[act.id] || 'none'];

  const userNote = activityNotes[act.id] ? `\n\n## 幹部私房備忘錄\n${activityNotes[act.id]}` : '';

  const text = `# 【活動企劃書】${act.title}
- 所屬分類：${act.category} · ${act.subType || ''} (${act.subtitle})
- 人數規模：${act.participants}
- 預計耗時：${act.duration}
- 建議地點：${act.location}
- 預算估計：${act.budget}
- 當前狀態：${statusLabel}${userNote}

## 一、活動概念與亮點
${act.summary}
★ 核心亮點：${act.highlight}

## 二、活動流程
${(act.schedule || []).map(s => `- **${s.time}**：${s.item}`).join('\n')}

## 三、規則公約
${act.rules}

## 四、物資清單
${(act.supplies || []).map(s => `- ${s}`).join('\n')}

## 五、幹部額外附註
${(act.extraNotes || []).map(n => `- ${n}`).join('\n')}

## 六、三位社員交叉對比審查評語
- **阿鐵 (硬核深淵技術黨)**：${((act.subType === '競技' || act.subType === '衝分')) ? '⭐⭐⭐⭐⭐ 極限壓輪、無傷走位與四星逆襲最考驗實力，規則公平且充滿熱血！' : (act.subType === '休閒') ? '不拼極限數值，大家同屏抽卡開盲盒氣氛極好，深淵打累後的最佳放鬆！' : '原以為手殘做不出來，但配備預製模具與速乾燈，連我這種只會按鍵盤的人都能一次成功！'}
- **悠悠 (佛系休閒氛圍黨)**：${(act.subType === '休閒') ? '⭐⭐⭐⭐⭐ 徹底告別劇本殺與上台簡報！零社恐、零尷尬，喝奶茶吃炸雞聊天超快樂！' : ((act.subType === '競技' || act.subType === '衝分')) ? '不用擔心自己練度不夠，現場設有觀戰競猜席與雙人手把賽，看神仙打架也超爽！' : '邊播原聲帶音樂邊動手捏周邊，完成後拍照發限動超級吸睛，完全沒時間壓力！'}
- **奇奇 (文創手作生活黨)**：${((act.subType === '手作' || act.subType === '動手製作')) ? '⭐⭐⭐⭐⭐ 無毒材料、嚴格控制在 90 分鐘內完工，100% 把精緻實體周邊帶回家！' : (act.subType === '休閒') ? '零食盲測評分與盲盒互換很有社交溫度，拍照紀錄發社刊超級好看！' : '賽後頒發手作專屬壓克力獎牌，並設有「手殘抽象搞笑獎」，人人有獎！'}
`;
  navigator.clipboard.writeText(text).then(() => {
    showToast(`已複製完整「${act.title}」企劃書 Markdown！`);
  });
}

// 匯出 JSON 檔案
function exportActivitiesJson() {
  const exportData = {
    activities: activitiesData,
    userState: {
      favorites: Array.from(favoriteIds),
      selected: Array.from(favoriteIds), // 相容舊版備份格式
      statuses: activityStatuses,
      notes: activityNotes,
      memberVotes: memberVotes,
      exportTime: new Date().toISOString()
    }
  };
  const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(exportData, null, 2));
  const downloadAnchor = document.createElement('a');
  downloadAnchor.setAttribute("href", dataStr);
  downloadAnchor.setAttribute("download", `activities_backup_${new Date().toISOString().slice(0, 10)}.json`);
  document.body.appendChild(downloadAnchor);
  downloadAnchor.click();
  downloadAnchor.remove();
  showToast("已成功下載包含個人備忘、投票統計與狀態的完整備份 JSON！");
}

// 輕量 Toast 提示
function showToast(message) {
  let toast = document.getElementById('toastMsg');
  if (!toast) {
    toast = document.createElement('div');
    toast.id = 'toastMsg';
    toast.className = 'toast-msg';
    document.body.appendChild(toast);
  }
  toast.textContent = message;
  toast.classList.add('show');
  setTimeout(() => {
    toast.classList.remove('show');
  }, 2600);
}

// ==========================================================================
// 4. 社員專屬篩選機制 (嚴格落實：社員匯入內容不計入喜好，除非點開該社員的篩選內容)
// ==========================================================================

// 點開該社員的篩選內容
function filterByMember(memberId) {
  const vote = memberVotes.find(v => v.id === memberId);
  if (!vote) return;

  activeMemberFilter = memberId;

  // 若當前在統計看板分頁，留在統計圖表，直接更新統計圖表，不切換頁面！
  if (currentCategory === 'stats') {
    renderStatsView();
    showToast(`已在圖表中顯示社員「${vote.name}」所選的心願活動！📊`);
    return;
  }

  // 若在企劃庫首頁，則維持首頁篩選活動卡片行為
  renderActiveMemberBanner();
  renderMemberQuickFilterChips();
  updateSubTypeBadges();
  renderCards();

  // 平滑滾動至卡片區域提示
  const banner = document.getElementById('activeMemberBanner');
  if (banner) {
    banner.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
  }

  showToast(`已點開社員「${vote.name}」的篩選內容（共 ${(vote.selectedIds || []).length} 項）！`);
}

// 清除社員專屬篩選，恢復全社活動庫檢視
function clearMemberFilter() {
  activeMemberFilter = null;

  // 若當前在統計看板分頁，留在統計圖表，直接重新渲染全社綜合統計圖表！
  if (currentCategory === 'stats') {
    renderStatsView();
    showToast('已恢復全社綜合統計圖表 📊');
    return;
  }

  renderActiveMemberBanner();
  renderMemberQuickFilterChips();
  updateSubTypeBadges();
  renderCards();
  showToast('已退出社員篩選，恢復完整活動庫檢視 🔄');
}

// 渲染社員篩選進行中橫幅
function renderActiveMemberBanner() {
  const banner = document.getElementById('activeMemberBanner');
  if (!banner) return;

  if (!activeMemberFilter) {
    banner.style.display = 'none';
    banner.innerHTML = '';
    return;
  }

  const vote = memberVotes.find(v => v.id === activeMemberFilter);
  if (!vote) {
    banner.style.display = 'none';
    return;
  }

  const count = (vote.selectedIds || []).length;
  banner.style.display = 'flex';
  banner.innerHTML = `
    <div class="active-member-banner-left">
      <span class="active-member-banner-badge">👤 社員選項篩選中</span>
      <span class="active-member-banner-text">
        目前正在檢視社員 <strong>${vote.name}</strong> 匯入之心願活動（共 <strong>${count}</strong> 份企劃）
      </span>
    </div>
    <button class="btn-clear-member-filter" onclick="clearMemberFilter()" type="button" title="點擊退出該社員篩選">
      ✕ 退出社員篩選
    </button>
  `;
}

// 渲染區塊一下方的社員快速篩選晶片按鈕列
// 渲染圖二左下角的社員快速篩選晶片按鈕列
function renderMemberQuickFilterChips() {
  const container = document.getElementById('memberFilterChipsContainer');
  const row = document.getElementById('memberQuickFilterRow');
  if (!container) return;

  // 僅在統計圖表狀態 (currentCategory === 'stats') 且有社員投票紀錄時顯示於圖二左下角
  if (currentCategory !== 'stats' || memberVotes.length === 0) {
    if (row) row.style.display = 'none';
    return;
  }
  if (row) row.style.display = 'flex';

  const targetMember = activeMemberFilter ? memberVotes.find(v => v.id === activeMemberFilter) : null;
  const isMemberMode = Boolean(targetMember);

  const allChip = `
    <button class="btn-member-filter-chip ${!isMemberMode ? 'active' : ''}" 
            onclick="clearMemberFilter()" type="button" title="檢視全社綜合統計圖表 (無社員篩選)">
      <svg class="mono-icon" viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
        <path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"></path>
        <circle cx="9" cy="7" r="4"></circle>
        <path d="M23 21v-2a4 4 0 0 0-3-3.87"></path>
        <path d="M16 3.13a4 4 0 0 1 0 7.75"></path>
      </svg>
      <span>全部</span>
    </button>
  `;

  const memberChips = memberVotes.map(vote => {
    const isActive = activeMemberFilter === vote.id;
    const count = (vote.selectedIds || []).length;
    return `
      <button class="btn-member-filter-chip ${isActive ? 'active' : ''}" 
              onclick="filterByMember('${vote.id}')" type="button" title="在圖表中顯示社員「${vote.name}」所選的心願活動">
        <svg class="mono-icon" viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
          <path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"></path>
          <circle cx="12" cy="7" r="4"></circle>
        </svg>
        <span>${vote.name}</span>
        <span class="chip-badge">${count}</span>
      </button>
    `;
  }).join('');

  container.innerHTML = allChip + memberChips;
}

